diff --git a/src/ui/text.h b/src/ui/text.h
index 19de968..95cc3a6 100644
--- a/src/ui/text.h
+++ b/src/ui/text.h
@@ -1,14 +1,14 @@
 #ifndef TEXT_H
 #define TEXT_H

-#include <stdint.h>
 #include <raylib.h>
 #include "fonts.h"

-// Single-line text: callers break lines themselves, and control characters draw nothing.
+// Single-line text: callers break lines themselves, and control characters draw nothing. Colour emoji draw untinted
+// from the font's line; .fnt and .bdf fonts have none.
 float text_measure(const VdFont *font, const char *text, int font_size);
-// What one codepoint adds to text_measure.
-float text_codepoint_width(const VdFont *font, uint32_t codepoint, int font_size);
+// What the cluster at text, an emoji or one codepoint, adds to text_measure; sets length to its bytes.
+float text_cluster_width(const VdFont *font, const char *text, int font_size, int *length);
 int text_line_height(const VdFont *font, int font_size);
 // position is the top-left of the line box.
 void text_draw(const VdFont *font, const char *text, Vector2 position, int font_size, Color color);

diff --git a/src/ui/text.c b/src/ui/text.c
index fadcadc..aac80fd 100644
--- a/src/ui/text.c
+++ b/src/ui/text.c
@@ -41,9 +41,40 @@ void text_upload_pages(void)
     }
 }

-float text_codepoint_width(const VdFont *font, uint32_t codepoint, int font_size)
+// Controls, zero width joiners and variation selectors.
+static bool draws_nothing(uint32_t codepoint)
 {
-    if (codepoint < 0x20) return 0.0f;
+    return codepoint < 0x20 || codepoint == 0x200d || (codepoint >= 0xfe00 && codepoint <= 0xfe0f);
+}
+
+typedef struct {
+    int length;
+    bool emoji;
+    VdGlyph glyph;
+    uint32_t codepoint;
+} Cluster;
+
+// An emoji, or one codepoint.
+static Cluster next_cluster(const VdFont *font, const char *text, int font_size)
+{
+    Cluster cluster = {0};
+    VdEmojiSequence sequence;
+    if (font->outline) {
+        int length = vd_emoji_cluster(text, &sequence);
+        if (length > 0) {
+            cluster.length = length;
+            cluster.emoji = true;
+            cluster.glyph = glyph_cache_get_emoji(font->outline, font_size, &sequence);
+            return cluster;
+        }
+    }
+    cluster.codepoint = vd_utf8_next(text, &cluster.length);
+    return cluster;
+}
+
+static float codepoint_width(const VdFont *font, uint32_t codepoint, int font_size)
+{
+    if (draws_nothing(codepoint)) return 0.0f;
     if (font->outline) return glyph_cache_get(font->outline, font_size, codepoint).advance + TEXT_SPACING;

     const Font *bitmap = &font->bitmap;
@@ -55,6 +86,14 @@ float text_codepoint_width(const VdFont *font, uint32_t codepoint, int font_size
     return advance * scale + TEXT_SPACING;
 }

+float text_cluster_width(const VdFont *font, const char *text, int font_size, int *length)
+{
+    Cluster cluster = next_cluster(font, text, font_size);
+    *length = cluster.length;
+    if (cluster.emoji) return cluster.glyph.advance + TEXT_SPACING;
+    return codepoint_width(font, cluster.codepoint, font_size);
+}
+
 float text_measure(const VdFont *font, const char *text, int font_size)
 {
     if (!font->outline) return MeasureTextEx(font->bitmap, text, (float)font_size, TEXT_SPACING).x;
@@ -62,7 +101,7 @@ float text_measure(const VdFont *font, const char *text, int font_size)
     float width = 0.0f;
     for (const char *p = text; *p != '\0';) {
         int length = 0;
-        width += text_codepoint_width(font, vd_utf8_next(p, &length), font_size);
+        width += text_cluster_width(font, p, font_size, &length);
         p += length;
     }
     return width > 0.0f ? width - TEXT_SPACING : 0.0f;
@@ -86,16 +125,16 @@ void text_draw(const VdFont *font, const char *text, Vector2 position, int font_
     float baseline = roundf(position.y + glyph_font_metrics(font->outline, font_size).ascent);
     float pen = position.x;
     for (const char *p = text; *p != '\0';) {
-        int length = 0;
-        uint32_t codepoint = vd_utf8_next(p, &length);
-        p += length;
-        if (codepoint < 0x20) continue;
+        Cluster cluster = next_cluster(font, p, font_size);
+        p += cluster.length;
+        if (!cluster.emoji && draws_nothing(cluster.codepoint)) continue;

-        VdGlyph glyph = glyph_cache_get(font->outline, font_size, codepoint);
+        VdGlyph glyph = cluster.emoji ? cluster.glyph : glyph_cache_get(font->outline, font_size, cluster.codepoint);
         if (glyph.page >= 0 && IsTextureValid(g_page_textures[glyph.page])) {
             Rectangle source = {(float)glyph.x, (float)glyph.y, (float)glyph.width, (float)glyph.height};
             Vector2 at = {roundf(pen) + (float)glyph.offset_x, baseline + (float)glyph.offset_y};
-            DrawTextureRec(g_page_textures[glyph.page], source, at, color);
+            Color tint = glyph.color ? (Color){255, 255, 255, color.a} : color;
+            DrawTextureRec(g_page_textures[glyph.page], source, at, tint);
         }
         pen += glyph.advance + TEXT_SPACING;
     }

diff --git a/src/ui/render.c b/src/ui/render.c
index 1f14614..aae70c8 100644
--- a/src/ui/render.c
+++ b/src/ui/render.c
@@ -121,14 +121,14 @@ static void text_layout_wrap_word(const char *paragraph, const VdFont *font, int
                 current_len = 0;
             }

-            // Chunks hold whole codepoints, and at least one even when it alone is too wide.
+            // Chunks hold whole clusters, and at least one even when it alone is too wide.
             int chunk_start = 0;
             while (chunk_start < word_len) {
                 int length = 0;
-                vd_utf8_next(word + chunk_start, &length);
+                text_cluster_width(font, word + chunk_start, font_size, &length);
                 int chunk_end = chunk_start + length;
                 while (chunk_end < word_len) {
-                    vd_utf8_next(word + chunk_end, &length);
+                    text_cluster_width(font, word + chunk_end, font_size, &length);
                     char probe[TEXT_LAYOUT_MAX_LINE_CHARS] = {0};
                     memcpy(probe, word + chunk_start, (size_t)(chunk_end + length - chunk_start));
                     if (measure_text_width(font, probe, font_size) > max_width) break;
@@ -349,7 +349,7 @@ static void render_button_instance(ReactInstance *inst, RenderContext ctx)
               button_font_size(b), b->text_color);
 }

-// The longest run of whole codepoints from the start of text, or with keep_end from its end, that fits max_width
+// The longest run of whole clusters from the start of text, or with keep_end from its end, that fits max_width
 // and out_size. Copies it into out and returns its width.
 static float fit_text(const VdFont *font, const char *text, int font_size, float max_width, bool keep_end, char *out,
                       size_t out_size)
@@ -358,22 +358,23 @@ static float fit_text(const VdFont *font, const char *text, int font_size, float
     size_t start = 0, end = 0;
     float width = 0.0f;
     if (keep_end) {
-        start = len;
+        // Clusters only parse forwards, so drop them from the start until the rest fits.
         end = len;
-        while (start > 0) {
-            size_t prev = start - 1;
-            while (prev > 0 && ((unsigned char)text[prev] & 0xc0) == 0x80)
-                prev--;
+        for (size_t at = 0; at < len;) {
             int size = 0;
-            float w = text_codepoint_width(font, vd_utf8_next(text + prev, &size), font_size);
-            if (width + w > max_width || end - prev >= out_size) break;
-            width += w;
-            start = prev;
+            width += text_cluster_width(font, text + at, font_size, &size);
+            at += (size_t)size;
+        }
+        while (start < len && (width > max_width || len - start >= out_size)) {
+            int size = 0;
+            width -= text_cluster_width(font, text + start, font_size, &size);
+            start += (size_t)size;
         }
+        if (start == len) width = 0.0f;
     } else {
         while (end < len) {
             int size = 0;
-            float w = text_codepoint_width(font, vd_utf8_next(text + end, &size), font_size);
+            float w = text_cluster_width(font, text + end, font_size, &size);
             if (width + w > max_width || end + (size_t)size >= out_size) break;
             width += w;
             end += (size_t)size;

